INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(692, 'plPL', 'Zaginione fragmenty', 'Zwój Myzrael... Zwój Myzrael?! Nie chcesz go! Jego magia może wyciągnąć Myzrael na powierzchnię świata, a jeśli do tego dojdzie, będziemy mieli kłopoty!$B$BAlbo... może już za późno. Może ona już jest wolna. Może tylko zbiera siły, zanim na nas uderzy. Jeśli tak, to zwój będzie ci POTRZEBNY!$B$B...szkoda, że został zniszczony. Rozwścieczone żywiołaki go ukradły, podarły na strzępy, a teraz walczą o fragmenty.$B$BAle jeśli zdołasz zebrać te fragmenty, może uda się go naprawić...', 'Przynieś podarty fragment zwoju, zmięty fragment zwoju i przypalony fragment zwoju Theldurinowi Zagubionemu.', '', 'Wróć do Theldurina Zagubionego na Bezludziu.', '', '', '', '', 0),
(703, 'plPL', 'Skrzydła sępa z grilla', 'O tak, moje skrzydła sępa z grilla to prawdziwy przysmak! Sos jest gęsty, a mięso pikantne. A zapach ściąga głodomorów z odległości wielu mil!$B$BMam wszystko, czego potrzeba, żeby przyrządzić porcję. Wszystko... oprócz skrzydeł sępa!$B$BJeśli chcesz spróbować, zdobądź mi skrzydła sępa. Przynieś ich dość, a może nawet zdradzę ci przepis!', 'Przynieś 4 skrzydła sępa Rigglefuzzowi.', '', 'Wróć do Rigglefuzza w Dolinie Kłów na Bezludziu.', '', '', '', '', 0),
(705, 'plPL', 'Nurkowanie po perły', 'Bezludzie to surowe miejsce, pełne groźnych drapieżników i zuchwałych padlinożerców. Strach tu żyć, zwłaszcza takiemu małemu goblinowi. Żeby przetrwać, muszę być sprytny!$B$BZnam przepis na bomby błyskowe. Używam ich, żeby odstraszać zwierzynę. Ale kończy mi się jeden ze składników: proszek z tłuczonych niebieskich pereł. Zdobądź mi trochę, a nie pożałujesz.$B$BHeh, i mam nadzieję, że masz porządne buty. Niebieskie perły, których potrzebuję, można znaleźć w małżach przy Plugawej Rafie.$B$BTak jest, przy Plugawej Rafie w Dolinie Cierniodławów!', 'Przynieś 9 niebieskich pereł Rigglefuzzowi na Bezludziu.', '', 'Wróć do Rigglefuzza w Dolinie Kłów na Bezludziu.', '', '', '', '', 0),
(706, 'plPL', 'Zaklęcia ognistych płomieni', 'Jako uczeń Feranora Stalopalcego poznałem jego szczególną technikę nasycania broni ognistymi zaklęciami. Ostatnio słyszałem, że pracuje w kuźni przy grupie myśliwych gdzieś w Lordaeronie.$b$bNie mogę zdradzić zbyt wielu szczegółów tego procesu, ale mogę powiedzieć, że wymaga krwi z rzadkiego, wciąż bijącego serca pisklęcia czarnego smokowca. Czekając na wieści z Żelaznej Kuźni, nie mam wiele do roboty. Jeśli przyniesiesz mi serce pisklęcia z Parowu Lethlor, pokażę ci, co potrafię!', 'Zdobądź serce czarnego smokowca dla Sigruna Żelaznoręba.', '', 'Wróć do Sigruna Żelaznoręba na Bezludziu.', '', '', '', '', 0),
(709, 'plPL', 'Ratunek przed zagładą', 'Ojej! Ojej! Nadciąga zagłada. Zapamiętaj moje słowa! Zagłada!$B$BNie, nie mogę o tym mówić... nie mogę wypowiedzieć ich imion, bo mogą mnie usłyszeć! Ale jeśli się dowiemy, tak, jeśli dowiemy się o nich więcej... to może dowiemy się, jak pokrzyżować im plany!$B$BMoże.$B$BIdź do Uldamanu. Nie! Powiedziałem to! Musisz znaleźć... znaleźć tabliczkę... Ryun\'eh. Tak, znajdź ją! I nie każ mi znowu wymawiać tego imienia!$B$BJest głęboko w tamtym miejscu, w pradawnej skrzyni. Tam się ukrywa... w skrzyni wykonanej, zanim jakikolwiek krasnolud cokolwiek stworzył.', 'Przynieś tabliczkę Ryun\'eh Theldurinowi Zagubionemu.', '', 'Wróć do Theldurina Zagubionego przy Kresie Agmonda na Bezludziu.', '', '', '', '', 0),
(710, 'plPL', 'Badanie żywiołów: skała', 'Zatrzymałem się tu, na Bezludziu, żeby popracować nad moim najnowszym projektem: kajdanami do wiązania żywiołaków.$B$BGdy będą gotowe, pozwolą magom przyzywać jeszcze potężniejsze żywiołaki do jeszcze poważniejszych zadań. Na początek potrzebuję małych kamiennych odłamków, żeby wypróbować kilka moich najnowszych zaklęć ofensywnych i parę zmyślnych urządzeń, które sam złożyłem.$B$BOdłamki łatwo zebrać z pomniejszych skalnych żywiołaków na zachód stąd. $GMógłbyś:Mogłabyś; mi trochę przynieść?', 'Znajdź 10 małych kamiennych odłamków i przynieś je Lotwilowi Veriatusowi na Bezludziu.', '', 'Wróć do Lotwila Veriatusa w Pylistej Niecce na Bezludziu.', '', '', '', '', 0),
(711, 'plPL', 'Badanie żywiołów: skała', '$N, już $gudowodniłeś:udowodniłaś;, że jesteś $gzdolniejszy:zdolniejsza; niż wszyscy moi uczniowie razem wzięci.$B$BNastępne części, których potrzebuję, wymagają nieco więcej siły. Duże kamienne płyty można zdobyć ze skalnych żywiołaków, jeśli zachowasz ostrożność. Ich ciała są silniejsze i większe, a więc częściej mają kawałki dość duże do moich testów. Znajdziesz je dalej na zachód stąd albo na południowym wschodzie, wzdłuż skraju gór.$B$BNie spiesz się; zbadanie tych mniejszych kawałków, które mi $gprzyniosłeś:przyniosłaś;, trochę mi zajmie.', 'Przynieś 3 duże kamienne płyty Lotwilowi Veriatusowi na Bezludziu.', '', 'Wróć do Lotwila Veriatusa w Pylistej Niecce na Bezludziu.', '', '', '', '', 0),
(712, 'plPL', 'Badanie żywiołów: skała', '$N, potrzebuję jeszcze jednej części od żywiołaków tu, na Bezludziu: karwaszy skalnych więzów od większych skalnych żywiołaków. Według moich obliczeń te karwasze powinny wystarczyć, by zmierzyć siłę moich własnych kajdan.$B$BGdy próbowałem wypatrzyć większe skalne żywiołaki za pomocą wróżenia, ujrzałem ich grupę na południowy zachód stąd, w pobliżu jakichś ogrów, o ile dobrze pamiętam.$B$BPrzynieś mi 5 ich karwaszy, żebym miał zapas. Serwo słynie z tego, że gubi moje odczynniki i notatki badawcze.', 'Przynieś 5 karwaszy skalnych więzów Lotwilowi Veriatusowi na Bezludziu.', '', 'Wróć do Lotwila Veriatusa w Pylistej Niecce na Bezludziu.', '', '', '', '', 0),
(713, 'plPL', 'Zimny olej, zimna krew', 'Coś ci powiem o oleju mrozu: nic tak nie chroni silnika ani trybów przed przegrzaniem.$B$BJego właściwości chłodzące są niezwykłe, a jako smar nie ma sobie równych pod względem trwałości. To nie wszystko: pomaga też utrzymać zaklęcia nałożone na magiczne przedmioty.$B$BPotrzebuję fiolki tego oleju, żeby zwiększyć magiczną pojemność moich kajdan i sprawić, by były dość potężne, żeby nasz przyzwany przyjaciel nie pozabijał nas wszystkich.$B$BBro\'kin, mój przyjaciel goblin, może cię nauczyć, jak go zrobić. Jest w Górach Alterak.', 'Znajdź olej mrozu i przynieś go Lotwilowi Veriatusowi na Bezludziu.', '', 'Wróć do Lotwila Veriatusa w Pylistej Niecce na Bezludziu.', '', '', '', '', 0),
(714, 'plPL', 'Żyro... co?', '$N, $gspisałeś:spisałaś; się ponad wszelkie normy.$B$B<Lotwil jest wyraźnie pochłonięty swoją pracą.>$B$BJeśli kiedyś spotkamy się w Kharanos, śmiało przyjdź do mnie po pracę.$B$BUps! Szybko, łap... tak, to. Dzięki.$B$BTeraz potrzebuję już tylko jednej rzeczy. To mała część, ale obawiam się, że dość kluczowa: żyrochronatom.$B$BGdybyś $gmógł:mogła; po prostu jakiś zdobyć i mi go przynieść, będę gotów to dokończyć.', 'Przynieś żyrochronatom Lotwilowi Veriatusowi na Bezludziu.', '', 'Wróć do Lotwila Veriatusa w Pylistej Niecce na Bezludziu.', '', '', '', '', 0),
(715, 'plPL', 'Płynny kamień', 'Coś mi się zdaje, $N, że te przedmioty, które $gzdobyłeś:zdobyłaś; dla Lotwila, to najmniejsze z naszych zmartwień. Z drugiej strony $gokazałeś:okazałaś; się aż nadto $gbiegły:biegła; w naukach, które Lotwil uważa za święte, więc może pomożesz i mnie?$B$BPotrzebuję mikstury niewidzialności i mikstury leczenia; obie mogą się wkrótce przydać, jeśli mu się to uda.$B$BW zamian dam ci recepturę na miksturę, nad którą pracuję, ucząc się u Lotwila. Opiera się na niektórych badaniach, które prowadzi tu, na Bezludziu.', 'Przynieś miksturę leczenia i mniejszą miksturę niewidzialności Lucienowi Tosselwrenchowi na Bezludziu.', '', 'Wróć do Luciena Tosselwrencha w Pylistej Niecce na Bezludziu.', '', '', '', '', 0),
(716, 'plPL', 'Kamień lepszy niż płótno', 'Wiem, jakim sknerą potrafi być Lotwil, $N, więc pozwól, że zrobię ci coś w zamian za wszystkie twoje trudy. Może to nawet ochroni cię przed nadciągającą katastrofą, jaką jest najnowszy wynalazek Lotwila.$B$BPracowałem nad tymi wszystkimi zapasowymi kamieniami, które dla niego $gzebrałeś:zebrałaś;, i mogę zrobić całkiem porządne karwasze, które mogą ci się przydać. Zaklęte, rzecz jasna.$B$BPotrzebuję tylko wzorzystych brązowych karwaszy wykutych przez kowala, żeby dokończyć te, które dla ciebie robię.', 'Przynieś wzorzyste brązowe karwasze Lucienowi Tosselwrenchowi na Bezludziu.', '', 'Wróć do Luciena Tosselwrencha w Pylistej Niecce na Bezludziu.', '', '', '', '', 0),
(717, 'plPL', 'Wstrząsy ziemi', 'Stało się jasne, że nie możemy zagwarantować, iż Blacklash i Hematus pozostaną uwięzieni w Lethlor. To, że osiedliły się tam czarne smoki, a ogrom udało się ukraść Znak, pokazuje, że trzeba będzie sięgnąć po bardziej drastyczne środki.$b$bWięzienie smokowców podtrzymują trzy kamienie runiczne, które można wydobyć tylko za pomocą Znaku Ziemi. Tymi kamieniami runicznymi można następnie złamać pieczęć, która ich więzi.$b$b$n... dopilnuj, by ich sny trwały wiecznie.', 'Użyj Znaku Ziemi, by aktywować filary ametystu, opalu i diamentu, i zdobądź kamienie runiczne.$b$bUmieść kamienie runiczne w Pieczęci Ziemi, by uwolnić Blacklasha i Hematusa.$b$bZabij ich i zanieś więzy Blacklasha, łańcuchy Hematusa oraz Znak Ziemi Garkowi.', '', 'Wróć do Garka na Wykopalisku Młotopalcego na Bezludziu.', '', '', '', '', 0),
(718, 'plPL', 'Miraże', 'W pośpiechu, z jakim opuszczaliśmy wykopaliska w Uldamanie, musieliśmy porzucić po drodze wiele wozów i skrzyń z zapasami. Miejscowe ogry z Obozu Kosh rzuciły się na nasz porzucony sprzęt jak sępy na gnijące truchło. I pachną niewiele lepiej. Niż to truchło, znaczy się.$b$bTak czy siak, zabrali wóz, który wiózł całą naszą broń i tak dalej... więc – no, to trochę wstydliwe – nie mamy jak zdobyć jedzenia.$b$bJesteśmy w niezłych tarapatach. Może byś nam $gpomógł:pomogła;?', 'Odzyskaj skrzynię z zapasami dla Sigruna Żelaznoręba.', '', 'Wróć do Sigruna Żelaznoręba na Bezludziu.', '', '', '', '', 0),
(719, 'plPL', 'Krasnolud i jego narzędzia', 'Hej, $N. Uważaj tu. Wszędzie wokół kręcą się Czarnoryci – wyglądało mi na klan Cienistej Kuźni.$B$BWłaśnie napadli na wykopalisko, przy którym robiłem – wybili prawie wszystkich, z moim szefem Młotopalcym włącznie. Ledwo uszedłem z życiem.$B$BWykopalisko jest zaraz na północ stąd, a ja kombinuję, jak odzyskać część naszych zapasów, zwłaszcza mój szczęśliwy kilof.$B$BMyślisz, że $gdałbyś:dałabyś; radę mi trochę pomóc? Któryś z tych przeklętych Czarnorytych musi mieć mój kilof! Może to być każdy z nich.', 'Znajdź szczęśliwy kilof Ryedola i oddaj go poszukiwaczowi Ryedolowi na południe od Wykopaliska Młotopalcego.', '', 'Wróć do poszukiwacza Ryedola na Bezludziu.', '', '', '', '', 0),
(720, 'plPL', 'Znak nadziei', '<Na mapie ktoś niedbale nabazgrał kredą kilka słów.>$B$B„Ryedol,$BZabierają mnie do Uldamanu. Przyślij pomoc.$B– Młotopalcy”', 'Znajdź poszukiwacza Ryedola i daj mu znać, że Młotopalcy Grez żyje.', '', 'Porozmawiaj z poszukiwaczem Ryedolem na Bezludziu.', '', '', '', '', 0),
(732, 'plPL', 'Wstrząsy ziemi', 'Słyszałem od Sigruna, że bardzo mu $gpomogłeś:pomogłaś;. Może i ja mógłbym liczyć na twoją pomoc. Przysłał mnie tu mój mistrz, Krasus z Kirin Toru, bym położył kres kłopotom, które narastają w Parowie Lethlor.$b$bNie mogę zdradzić dokładnej natury mojej misji ani zadań, których muszę się podjąć, ale zapewniam cię, że to sprawa najwyższej wagi.$b$bBanda wędrownych ogrów, widywana czasem w pobliżu Obozu Boff, ukradła przedmiot zwany Znakiem Ziemi; muszę go mieć. Przynieś mi go, a powiem ci więcej.', 'Odzyskaj Znak Ziemi dla Garka.', '', 'Wróć do Garka na Wykopalisku Młotopalcego na Bezludziu.', '', '', '', '', 0),
(733, 'plPL', 'Trzeba coś skombinować', 'Ciężko tu będzie, jeśli nie zdołam skombinować trochę materiałów na umocnienia i inne niezbędne rzeczy. Zauważyłem, że tutejsze ogry są nieźle zaopatrzone w złom. Może te opowieści o machinach oblężniczych na Bezludziu wcale nie były takie przesadzone...$b$bTak czy siak, Poszukiwacz zaczyna się martwić o stan naszego obozowiska, więc chciałbym jak najszybciej wziąć się do roboty.$b$bGłówny obóz ogrów jest w Grocie Pyłoodbicia, spory kawał drogi na zachód stąd.', 'Zdobądź 7 kawałków złomu dla Sigruna.', '', 'Wróć do Sigruna Żelaznoręba na Bezludziu.', '', '', '', '', 0),
(734, 'plPL', 'To będzie trudne', 'Wspaniale, wspaniale.$B$B<Lotwil na chwilę podnosi na ciebie wzrok, po czym wraca do swoich kajdan.>$B$BIdź porozmawiać z Lucienem, $N. Potrzebuję zębatki nr 5. Przyniesiesz mi ją, dobrze?', 'Porozmawiaj z Lucienem Tosselwrenchem na Bezludziu.', '', '', '', '', '', '', 0),
(777, 'plPL', 'To będzie trudne', 'Dobra, proszę bardzo.$B$BJa będę tam... w ukryciu.$B$BŚmiało możesz do mnie dołączyć.', 'Zanieś zębatkę nr 5 Lotwilowi Veriatusowi.', '', 'Wróć do Lotwila Veriatusa na Bezludziu.', '', '', '', '', 0),
(778, 'plPL', 'To będzie trudne', 'Haha! Gotowe! Kajdany są gotowe!$B$BNadszedł czas, Lucienie. Nadszedł czas, Serwo!$B$BJesteś $ggotów:gotowa; być świadkiem doskonałego połączenia alchemii, inżynierii i magii tajemnej, $N?$B$BTeraz przyzwę potężnego żywiołaka. To przełomowy dzień dla nas wszystkich.', 'Pokonaj Strażnika Fam\'retor i odnieś kajdany Lotwila do wiązania żywiołaków Lotwilowi Veriatusowi.', '', 'Wróć do Lotwila Veriatusa w Pylistej Niecce na Bezludziu.', '', '', '', '', 0),
(779, 'plPL', 'Pieczęć Ziemi', '', '', '', 'Wróć do Pieczęci Ziemi na Bezludziu.', '', '', '', '', 0),
(782, 'plPL', 'Zerwane sojusze', 'Z czasów sojuszu Hordy ze smokiem Śmiercioskrzydłym podczas Drugiej Wojny wiemy, że dwóch jego poruczników, Blacklash i Hematus, zostało uwięzionych w Parowie Lethlor daleko na wschodzie. Musimy uciszyć naszych dawnych, zdeprawowanych sojuszników, by przywrócić Hordzie honor!$B$BWynajęliśmy Tho\'gruna i jego bandę ogrzych najemników, żeby pomogli nam zdobyć Znak Ziemi, klucz potrzebny do otwarcia więzienia smokowców. Tho\'grun jednak nas zdradził – rozgromił nas i zagarnął Znak dla siebie. Idź do Obozu Boff i odbierz go!', 'Zabij szefa Tho\'gruna i przynieś Znak Ziemi Gornowi w Kargacie.', '', 'Wróć do Gorna w Kargacie na Bezludziu.', '', '', '', '', 0),
(793, 'plPL', 'Zerwane sojusze', 'Pieczęć Ziemi utrzymują trzy kamienie runiczne osadzone w filarach diamentu, opalu i ametystu w Parowie Lethlor. Za pomocą Znaku Ziemi zdołasz wyjąć kamienie runiczne i otworzyć Pieczęć Ziemi.$b$bUważaj jednak, $n: z czarnymi smokowcami Blacklashem i Hematusem nie ma żartów. Dopilnuj, by zginęli, i przynieś mi ich więzy.$B$BŻeby dotrzeć do parowu, udaj się na najdalszy wschodni skraj Bezludzia. Bądź jednak $gostrożny:ostrożna;, bo w parowie roi się od smokowców.', 'Użyj Znaku Ziemi, by aktywować filary diamentu, opalu i ametystu, i zdobądź kamienie runiczne.$b$bUmieść kamienie runiczne w Pieczęci Ziemi, by uwolnić Blacklasha i Hematusa.$b$bZabij ich i zanieś więzy Blacklasha, łańcuchy Hematusa oraz Znak Ziemi Gornowi.', '', 'Wróć do Gorna przy Spoczynku Apokryfana na Bezludziu.', '', '', '', '', 0),
(795, 'plPL', 'Pieczęć Ziemi', '', '', '', 'Wróć do Pieczęci Ziemi na Bezludziu.', '', '', '', '', 0),
(1418, 'plPL', 'Neeka Krwawa Blizna', 'Bezludzie to surowa kraina, a leży blisko Loch Modan, ziem w rękach Przymierza, więc łączność między Stonardem a posterunkiem Hordy na Bezludziu, Kargatem, często bywa zrywana.$B$BWykaż się, $N. Udaj się na Bezludzie i porozmawiaj z Neeką Krwawą Blizną, główną zwiadowczynią posterunku w Kargacie. Porozmawiaj z nią, a potem odeślij mi jej raport.', 'Porozmawiaj z Neeką Krwawą Blizną.', '', '', '', '', '', '', 0),
(1419, 'plPL', 'Kojoty złodzieje', '$GSpędziłeś:Spędziłaś; wiele dni na Bezludziu, $N? $GCzułeś:Czułaś; jego żar? $GStawałeś:Stawałaś; do walki z bestiami, które przemierzają jego pyliste równiny? Czas, żebyś to $gzrobił:zrobiła;.$B$BSkalne kojoty to twarda rasa. Twarda i na tyle zuchwała, że zakradają się do Kargatu i kradną nasze zapasy jedzenia. Pomóż oczyścić posterunek z tych złodziei!$B$BPoluj na skalne kojoty, $N. Poluj na nie i przynieś mi ich żuchwy. Przynieś ich dość, a może uwierzę, kiedy powiesz, że znasz Bezludzie.', 'Przynieś 30 żuchw kojota Neece Krwawej Bliźnie w Kargacie.', '', 'Wróć do Neeki Krwawej Blizny przy Spoczynku Apokryfana na Bezludziu.', '', '', '', '', 0),
(1420, 'plPL', 'Raport dla Helgruma', 'Napisałam świeży raport dla Helgruma w Stonardzie. Zanieś mu go.$B$BA jeśli uważasz się za gońca, to nie zgub drogi. Ani nie padnij z ręki wroga.', 'Zanieś raport Neeki Helgrumowi Chyżemu w Stonardzie.', '', '', '', '', '', '', 0),
(1559, 'plPL', 'Schemat bomby błyskowej', '', '', '', '', '', '', '', '', 0),
(2202, 'plPL', 'Składniki z Uldamanu', 'Słyszałem o niedawno odkrytej roślinie, którą nazywają purpurowymi kapeluszami grzyba. Rosną w kępach na wykopaliskach w Uldamanie – można je znaleźć w pierwszych tunelach i głęboko w mniej zbadanych częściach. Chcę zbadać, czy nadają się do alchemii, i tu właśnie wkraczasz ty.$B$BZnajdź kępy purpurowych kapeluszy i przynieś mi tuzin kapeluszy. Tylko uważaj: potrącone kępy potrafią sypnąć trującymi zarodnikami.$B$BZrób to dla mnie, a upichcę ci porcję jednego z moich słynnych przywracających eliksirów!', 'Przynieś 12 purpurowych kapeluszy grzyba Jarkalowi Mchosplotowi w Kargacie.', '', 'Wróć do Jarkala Mchosplota w Kargacie na Bezludziu.', '', '', '', '', 0),
(2203, 'plPL', 'Składniki z Bezludzia II', 'Bardzo mi $gpomogłeś:pomogłaś;, $N. Nagrodziłbym cię samą recepturą na wywar, który ci wcześniej dałem... ale muszę cię prosić o zadanie, i to całkiem niebezpieczne. Wysłuchaj mojej prośby.$B$BW tej kasetce są trzy puste naczynia taumaturgiczne; przepaja je aura dostrojenia, która wyssie krew ze smoka zwanego osmalonym strażnikiem. Użycie naczynia na bestii mocno ją rozwścieczy, więc uważaj. Kiedy napełnisz wszystkie trzy, przynieś mi je.$B$BZrób to, a receptura będzie twoja.', 'Użyj pustych naczyń taumaturgicznych na osmalonych strażnikach, smokach z Bezludzia. Kiedy je napełnisz, zanieś je Jarkalowi Mchosplotowi w Kargacie.', '', 'Wróć do Jarkala Mchosplota w Kargacie na Bezludziu.', '', '', '', '', 0),
(2258, 'plPL', 'Składniki z Bezludzia', '$N, przydałaby mi się twoja pomoc, jeśli masz ochotę. Jestem alchemikiem niemałej sławy i szukam pomocy w zdobyciu pewnych składników, które można znaleźć na Bezludziu.$B$BŻeby uzupełnić zapasy, potrzebuję następujących rzeczy: pięciu żołądków sępa, dziesięciu kłów skalnego kojota i pięciu odłamków skalnego żywiołaka. Oczywiście zdobędziesz je z samych bestyjek; jeśli walka to nie twoja specjalność, znajdź przyjaciół, dla których jest.$B$BZdobądź dla mnie te rzeczy, a zarobisz na tym trochę grosza. No to jak będzie?', 'Przynieś 5 żołądków sępa, 10 kłów skalnego kojota i 5 odłamków skalnego żywiołaka Jarkalowi Mchosplotowi w Kargacie na Bezludziu.', '', 'Wróć do Jarkala Mchosplota w Kargacie na Bezludziu.', '', '', '', '', 0),
(2278, 'plPL', 'Platynowe dyski', 'Centralne miejsce tej komnaty skarbów zajmują cztery ogromne platynowe dyski, każdy ozdobiony licznymi symbolami nieznanego pochodzenia. Gdy ich dotykasz, czujesz mrowienie w dłoni. Tuż po dotknięciu dysków pojawia się wizerunek wielkiego kamiennego obserwatora.$B$B„Pozdrowienia. Jestem strażnikiem wiedzy. Synteza ziemnych dokonana przez Stwórców została opisana i przechowana tutaj, dla tego świata, w Dyskach Norgannona”.$B$BOdkrywasz bogactwo nieznanej dotąd wiedzy o świecie!', 'Porozmawiaj z kamiennym obserwatorem i dowiedz się, jaką pradawną wiedzę przechowuje. Gdy poznasz wiedzę, którą ma do przekazania, uruchom Dyski Norgannona.', 'Poznaj wiedzę, którą ma do przekazania kamienny obserwator', 'Użyj Dysków Norgannona.', '', '', '', '', 0),
(2318, 'plPL', 'Tłumaczenie dziennika', 'Utknąwszy w martwym punkcie, wiesz, że trzeba będzie przetłumaczyć księgę na język, który rozumiesz. Z pewnością na świecie jest wiele osób, które by to potrafiły; najbliższym miejscem, gdzie może się znaleźć ktoś taki, jest jednak posterunek w Kargacie na Bezludziu. Być może warto od niego zacząć.$B', 'Znajdź kogoś, kto przetłumaczy dziennik paladyna. Najbliższym miejscem, gdzie ktoś taki może być, jest Kargat na Bezludziu.', '', '', '', '', '', '', 0),
(2338, 'plPL', 'Tłumaczenie dziennika', 'Ci ze Złomowiska Droffers i Syn nie są dość bystrzy, żeby przywrócić magię naszyjnika, ale ja jestem. Chcę tylko zbadać naszyjnik, żeby nauczyć się robić takie samemu. Do tego potrzebuję twojego naszyjnika. Pożycz mi go, a w zamian za czas na jego badanie przetłumaczę ci dziennik. Zanim znajdziesz klejnoty, powinienem zdążyć dowiedzieć się tego, czego potrzebuję.$B$BProsty układ i nikt się o niczym nie dowie. No to jak będzie?', 'Pożycz Jarkalowi naszyjnik. W zamian przetłumaczy ci dziennik.', '', '', '', '', '', '', 0),
(2339, 'plPL', 'Znajdź klejnoty i źródło mocy', 'Oto dziennik, przetłumaczony – możesz go sobie przeczytać. Sedno jest takie: krasnoludy ukryły rubin, troggi ukryły topaz, a szafir ma trogg imieniem Grimlok.$B$BSłuchaj – żeby naszyjnik znów działał, będzie ci potrzebne źródło mocy. Dran Droffers o tym nie wie. Ja na twoim miejscu zrobiłbym tak: zejdź tak głęboko w Uldaman, jak się da, i zabij najsilniejszy konstrukt, jaki tam jest. Bez wątpienia to on je ma.$B$BKiedy wszystko zbierzesz, wracaj tutaj!', 'Odzyskaj z Uldamanu wszystkie trzy klejnoty i źródło mocy do naszyjnika, a potem zanieś je Jarkalowi Mchosplotowi w Kargacie. Jarkal sądzi, że źródło mocy może mieć najsilniejszy konstrukt w Uldamanie.$B$BZ dziennika wiesz, że...$B* Rubin ukryto na zabarykadowanym terenie Cienistej Kuźni.$B* Topaz schowano w urnie na jednym z terenów troggów, w pobliżu krasnoludów z Przymierza.$B* Szafir przywłaszczył sobie Grimlok, przywódca troggów.', '', 'Wróć do Jarkala Mchosplota w Kargacie na Bezludziu.', '', '', '', '', 0),
(2418, 'plPL', 'Kamienie mocy', 'Jakiś czas temu miałem pewien incydent z krasnoludami z Cienistej Kuźni. Zabrali mnie do Fortecy Angor, żebym zbadał dwa rodzaje dziwnych kamieni z Uldamanu. Odkryłem, że te kamienie to trwałe, stabilne źródła mocy, jeśli się z nimi właściwie obchodzić. Niesamowite, co można znaleźć w tych starych wykopaliskach!$B$BW każdym razie kiedy zdradziłem im sekret kamieni, wykopali mnie z Fortecy Angor i zaczęli kopać w Uldamanie w poszukiwaniu kolejnych.$B$BChcę mieć te kamienie dla siebie! Przynieś mi oba rodzaje, a sowicie ci zapłacę!', 'Przynieś 8 kamieni mocy z dentrium i 8 kamieni mocy z an\'alleum Rigglefuzzowi na Bezludziu.', '', 'Wróć do Rigglefuzza w Dolinie Kłów na Bezludziu.', '', '', '', '', 0),
(3821, 'plPL', 'Skała Upiornych Maczug', 'Ponad trzy tygodnie temu Sha\'ni wysłano, by zbadała doniesienia o dziwnych rytuałach ogrów z Ognistych Trzewi na Płonących Stepach.$B$BKrwawokieł mówi, że nie ma żadnych wieści od nikogo z tego plutonu i że najlepiej będzie, jeśli dam sobie spokój i skupię się na swoich zadaniach. Wyobrażasz sobie? To moja żona!$B$BNie mogę opuścić posterunku, $N, ale muszę wiedzieć, co się stało z Sha\'ni. Udaj się na Płonące Stepy i jej poszukaj.', 'Wyrusz na Płonące Stepy i dowiedz się, co się stało z Sha\'ni Dumny Kieł.', '', '', '', '', '', '', 0),
(3822, 'plPL', 'Krom\'Grul', 'Cały mój pluton wzięto do niewoli, $N. Wszystkich zabito – oprócz mnie.$B$BIch przywódca, Krom\'Grul, chciał mnie zachować na jakiś rytuał.$B$BPrzykuto mnie do tego ołtarza, a bestia mnie katowała. Po godzinie tych tortur moje ciało przestało funkcjonować. Potem bestia zerwała mi z twarzy mój ślubny kolczyk do nosa i nasadziła go sobie na palec. Nigdy nie widziałam takiego okrucieństwa!$B$BZnajdź Krom\'Grula i zabij go! Zanieś mój kolczyk Thal\'trakowi.$B$BI, $N, powiedz mu, że spotkamy się znowu... w innym życiu.', 'Odzyskaj kolczyk do nosa Sha\'ni od Krom\'Grula i zanieś go Thal\'trakowi w Kargacie. Przeszukaj jaskinie i kopalnie na Skale Upiornych Maczug.$B', '', 'Wróć do Thal\'traka Dumnego Kła w Kargacie na Bezludziu.', '', '', '', '', 0),
(3906, 'plPL', 'Dysharmonia płomienia', 'Starszyzna wyczuła zaburzenie wśród żywiołów. Czarnoryci przyzwali do naszego świata plugawego ducha, który grozi, że nasze ziemie nawiedzi wieczna susza. Tę dysharmonię płomienia trzeba zbadać.$B$BUdaj się do Czarnej Góry, przez Rozpadlinę Płomieni, do kamieniołomu. Tam znajdziesz tego władcę ognia: nadmistrza Pyrona.$B$BPołóż kres temu zakłóceniu i wróć do mnie.', 'Udaj się do kamieniołomu w Czarnej Górze i zabij nadmistrza Pyrona. Gdy wykonasz to zadanie, wróć do Gromoserca.$B', '', 'Wróć do Gromoserca w Kargacie na Bezludziu.', '', '', '', '', 0),
(3907, 'plPL', 'Dysharmonia ognia', 'Czuję smak plugastwa w powietrzu, które cię otacza, $N. W głębinach Czarnej Góry ukrywa się jeszcze ktoś, kto włada tym plugastwem.$B$BWiatr i ziemia wykrzykują jego imię: lord Incendius... ale ktoś... coś... rozkazuje tej istocie. On jest tylko wysłannikiem.$B$BZnajdź go i odkryj, gdzie ukrywa się jego pan. Wróć do mnie, gdy zdobędziesz te informacje.$B', 'Wejdź do Otchłani Czarnej Góry i wytrop lorda Incendiusa. Zabij go i zanieś Gromosercu każde źródło informacji, jakie zdołasz znaleźć.$B', '', 'Wróć do Gromoserca w Kargacie na Bezludziu.', '', '', '', '', 0),
(3911, 'plPL', 'Ostatni żywioł', 'Dla tych, którzy zapuszczają się w głębiny, znajdzie się robota, $N.$B$BCzarnoryci opanowali tworzenie niezwykle potężnych golemów.$B$BPierwsze raporty naszych szpiegów wskazują, że krasnoludy używają wyjątkowego źródła mocy, które daje ich tworom niezrównaną siłę zabijania.$B$BWyobraź sobie tylko, co moglibyśmy zrobić z naszymi plugastwami, gdybyśmy położyli ręce na tej esencji żywiołów! Wywróć to miasto do góry nogami, jeśli trzeba, ale nie wracaj, dopóki nie znajdziesz esencji! Zapłata będzie warta ryzyka.', 'Udaj się do Otchłani Czarnej Góry i zdobądź 10 esencji żywiołów. Najpierw przychodzi ci do głowy, by przeszukać golemy i ich twórców. Pamiętasz też, że Vivian Lagrave mamrotała coś o żywiołakach.$B', '', 'Wróć do magini cienia Vivian Lagrave przy Spoczynku Apokryfana na Bezludziu.', '', '', '', '', 0),
(3981, 'plPL', 'Dowódca Gor\'shak', 'Biedny Gargal... nawet nie zauważył, co nadlatuje. ŁUP! Strzała trafiła go w sam czubek głowy. Geniuszem nie był już wcześniej, ale teraz...$B$B<Galamav się krzywi.>$B$BKiedy wyciągnęliśmy strzałę, zauważyliśmy przywiązany do drzewca zwinięty liścik. Na liściku był nieudolnie narysowany ork za kratami i podpis dowódcy Gor\'shaka.$B$BJeśli wciąż żyje w Otchłani, musisz go odnaleźć.$B$BPułapka, mówisz? No co ty nie powiesz, tępe kopyto! Właśnie dlatego to ty idziesz!$B', 'Odnajdź dowódcę Gor\'shaka w Otchłani Czarnej Góry.$B$BPamiętasz, że na nieudolnym rysunku orka portret był przekreślony narysowanymi kratami. Może warto poszukać jakiegoś więzienia.', '', '', '', '', '', '', 0),
(4061, 'plPL', 'Bunt maszyn', 'Maszyny dały o sobie znać podczas naszych pierwszych wypraw do Płonącego Wąwozu. Po dalszym dochodzeniu odkryliśmy, że sprowadzano je z Płonących Stepów, być może z Otchłani Czarnej Góry. Do tego właśnie jesteś nam $gpotrzebny:potrzebna;, $N.$B$BTwoim pierwszym zadaniem jest udać się na Płonące Stepy i zdobyć odłamki żywiołaków ze skalnych automatonów i pomniejszych skalnych tworów w tamtym regionie. Gdy zbierzesz ich dość, wróć do mnie, a ustalę, skąd pochodzą.$B', 'Wyrusz na Płonące Stepy i zdobądź 10 pękniętych odłamków żywiołaków dla hierofantki Theodory Mulvadanii.$B$BPamiętasz, że według Theodory źródłem tych odłamków są golemy i żywiołaki z tamtych stron.', '', 'Wróć do hierofantki Theodory Mulvadanii w Kargacie na Bezludziu.', '', '', '', '', 0),
(4062, 'plPL', 'Bunt maszyn', 'W.G.A.$B$BTo właśnie te „inicjały” odciśnięte na odłamkach żywiołaków. Pod inicjałami widnieje jakieś oznaczenie rangi. Maszyny, które $gzniszczyłeś:zniszczyłaś; na Płonących Stepach, miały „rangę IV”. Zakładam, że to niska ranga.$B$BZanieś tę próbkę odłamka Lotwilowi Veriatusowi do obozu na wschodzie. To dość znany uczony w dziedzinie nauk o żywiołach. Może pomoże nam w poszukiwaniach.', 'Zanieś próbkę odłamka żywiołaka Lotwilowi Veriatusowi.$B$BPamiętasz, że według Theodory Lotwil stacjonuje w obozie na wschodzie.$B', '', 'Zamelduj się u Lotwila Veriatusa na Bezludziu.', '', '', '', '', 0),
(4063, 'plPL', 'Bunt maszyn', 'To nie może być Argelmach! Argelmach zginął dziesięć lat temu. Skąd mam pewność? Sam go zabiłem.$B$BTo był nikczemny krasnolud, który za wszelką cenę chciał nagiąć dzieło mojego życia do swoich diabolicznych potrzeb. Wygląda na to, że niegodziwcy zawsze znajdą sposób, by umknąć sprawiedliwości.$B$BJeśli to dzieło Argelmacha, trzeba go zniszczyć. Będę potrzebował próbek jego najnowszych tworów. Mając odpowiednie próbki, może zdołam powstrzymać to powstanie. Twory te strzegą Argelmacha w Otchłani Czarnej Góry.', 'Znajdź i zabij Władcę Golemów Argelmacha. Zanieś jego głowę Lotwilowi. Musisz też zebrać 10 nienaruszonych rdzeni żywiołaków z golemów grabieżców gniewu i konstruktów siewców wojny, które strzegą Argelmacha. Wiesz o tym, bo masz zdolności jasnowidzenia.', '', 'Wróć do Lotwila Veriatusa na Bezludziu.', '', '', '', '', 0),
(4081, 'plPL', 'ZABIĆ NA MIEJSCU: Czarnoryci', 'Na rozkaz wodza Krwawokła, dowódcy Sił Ekspedycyjnych Kargatu:$B$BWszelkie siły generała Kuźni Gniewu w Otchłani Czarnej Góry mają zostać unicestwione.$B$BLudzie Kuźni Gniewu to bezlitośni zabójcy, odpowiedzialni za masowy mord na 109. dywizji Sił Ekspedycyjnych Kargatu. Ostrzega się bohaterów, by zachowali najwyższą ostrożność w starciu z tymi brutalami.$B$BKażdy, kto zniszczy pierwszą linię sił generała Kuźni Gniewu w Otchłani Czarnej Góry, otrzyma nagrodę.', 'Wyrusz do Otchłani Czarnej Góry i zniszcz podłych napastników!$B$BWódz Krwawokieł chce, żebyś $gzabił:zabiła; 15 gwardzistów Gniewnego Kowadła, 10 dozorców Gniewnego Kowadła i 5 piechurów Gniewnego Kowadła. Gdy wykonasz zadanie, wróć do niego.$B', '', 'Wróć do wodza Krwawokła w Kargacie na Bezludziu.', '', '', '', '', 0),
(4082, 'plPL', 'ZABIĆ NA MIEJSCU: wysocy rangą oficjele Czarnorytych', 'Na rozkaz wodza Krwawokła, dowódcy Sił Ekspedycyjnych Kargatu:$B$BSzef wydziału zwiadu S.E.K., arcymistrz Lexlort, powrócił z wieściami o miejscu pobytu wysokich rangą oficjeli Czarnorytych. Za zamkniętą bramą, blisko serca miasta, szkolą swoje siły, by wybić naszych ludzi. Udaj się do Otchłani Czarnej Góry i zniszcz ich!$B$BWykonanie tej misji zostanie nagrodzone.$B', 'Wyrusz do Otchłani Czarnej Góry i zniszcz podłych napastników!$B$BWódz Krwawokieł chce, żebyś $gzabił:zabiła; 10 medyków Gniewnego Kowadła, 10 żołnierzy Gniewnego Kowadła i 10 oficerów Gniewnego Kowadła. Gdy wykonasz zadanie, wróć do niego.', '', 'Wróć do wodza Krwawokła w Kargacie na Bezludziu.', '', '', '', '', 0),
(4121, 'plPL', 'Kłopotliwe położenie', 'Naprawdę wierzysz, że dotrzesz ze mną na miejsce spotkania? Naprawdę $gsądziłeś:sądziłaś;, że wedrzesz się do silnie ufortyfikowanej twierdzy Czarnej Skały i porwiesz jej cennego sojusznika, nie alarmując nikogo ani niczego?$B$BZginiesz!$B', 'Odeskortuj swojego więźnia, Grarka Lorkruba, przez Płonące Stepy i Czarną Górę do Płonącego Wąwozu.$B$BPamiętasz, że Lexlort wspominał, iż po drugiej stronie będą czekać jego ludzie, by przejąć Grarka.$B$BMusisz też oddać Lexlortowi swoje kajdany z torium.', 'Transport więźnia', 'Wróć do Lexlorta w Kargacie na Bezludziu.', '', '', '', '', 0),
(4122, 'plPL', 'Grark Lorkrub', 'Tropiłem go przez Płonący Wąwóz, przez górę, aż na Płonące Stepy. Ten zdrajca został przyłapany na gorącym uczynku, gdy przekazywał orkom z Czarnej Skały ważne informacje o naszych codziennych działaniach. Mówię o Grarku Lorkrubie.$B$BSiedzi teraz na Płonących Stepach, bezpieczny pod ich ochroną – a przynajmniej tak mu się wydaje.$B$BWeź te kajdany, $N. Znajdź Grarka, zakuj go i przeprowadź przez Czarną Górę. Zrób to, a nagroda będzie twoja.$B', 'Udaj się na Płonące Stepy i odnajdź Grarka Lorkruba. Pamiętasz, że według Lexlorta ostatnio widziano go w ogromnej twierdzy Czarnej Skały.$B$BGdy znajdziesz Grarka Lorkruba, skuj go kajdanami z torium i przeprowadź z powrotem przez Czarną Górę do Płonącego Wąwozu. Ludzie Lexlorta będą czekać po drugiej stronie, by przejąć Grarka.$B', '', '', '', '', '', '', 0),
(4132, 'plPL', 'Operacja „Śmierć Kuźni Gniewu”', '$GSpisałeś:Spisałaś; się wzorowo, $N. Czas wysłać cię na ostatnią misję.$B$BGenerał Kuźnia Gniewu, Czarnoryty odpowiedzialny za koordynowanie ataków na 109. dywizję S.E.K. i masową rzeź naszych sił, musi ponieść karę.$B$BTo bez wątpienia będzie twoja najcięższa misja, ale jeśli ci się powiedzie, zostaniesz sowicie $gwynagrodzony:wynagrodzona;.$B', 'Udaj się do Otchłani Czarnej Góry i zabij generała Kuźnię Gniewu! Gdy wykonasz zadanie, wróć do wodza Krwawokła.', '', 'Wróć do wodza Krwawokła w Kargacie na Bezludziu.', '', '', '', '', 0),
(4134, 'plPL', 'Zaginiony przepis Gromowarów', 'Krążą plotki, że Czarnoryty Hurley Czarnodech ukradł przepis na piwo. To piwo, Lager Gromowarów, podobno napełnia pijącego wielką siłą i odwagą. Chcemy zbadać ten trunek. Może znajdziemy inne zastosowania dla jego zalet... zastosowania bardziej zgodne z celami Porzuconych.$B$BZejdź do Otchłani Czarnej Góry, znajdź Hurleya, odbierz mu przepis na Lager Gromowarów i przynieś go mnie.$B$BA żeby go znaleźć, być może trzeba będzie go wywabić, zagrażając jego cennemu piwu.', 'Przynieś zaginiony przepis Gromowarów Vivian Lagrave w Kargacie.', '', 'Wróć do magini cienia Vivian Lagrave w Kargacie na Bezludziu.', '', '', '', '', 0),
(4724, 'plPL', 'Pani sfory', 'Niektórzy mówią, że worgi, którymi władają orkowie z Czarnej Skały, zostały stworzone przez nadprzyrodzoną siłę. Inni twierdzą, że to wcale nie prawdziwe worgi, lecz rasa demonicznych psów, którą orkom podarował upadły lord otchłani.$B$BPrawda jest znacznie mniej wydumana, ale równie przerażająca. Worgi z Czarnej Skały pochodzą od Halycon i jej partnera. Halycon to gigantyczna matka worgów, pani całego legowiska. A jej partner? Nikt jeszcze nie przeżył spotkania z nim, by o tym opowiedzieć.$B$BUderz w samo serce worgów. Zniszcz Halycon... i, $N, pilnuj pleców.', 'Zabij Halycon, panią sfory worgów Krwawego Topora.', '', 'Wróć do Galamava Strzelca w Kargacie na Bezludziu.', '', '', '', '', 0),
(4768, 'plPL', 'Tablica z mrocznego kamienia', 'Tablica z mrocznego kamienia zawiera zapiski dawno zmarłego krasnoluda Urhelda Mrocznego Kamienia. Był to niezwykle biegły alchemik, lecz współcześni uważali go za szaleńca, więc nie dzielił się swoimi badaniami.$B$BWyrył je jednak na tablicach i sądzę, że jedna z nich leży w Iglicy Czarnej Góry, w komnacie zwanej niegdyś Salą Fortuny. Nie wiem, jak nazywa się teraz, bo niewielu z tych, którzy wchodzą do Czarnej Góry, stamtąd wraca.$B$BAle jeśli $godważysz:odważysz; się stawić czoła tamtejszym niebezpieczeństwom i przyniesiesz mi tablicę, sowicie cię wynagrodzę.', 'Przynieś tablicę z mrocznego kamienia magini cienia Vivian Lagrave w Kargacie.', '', 'Wróć do magini cienia Vivian Lagrave przy Spoczynku Apokryfana na Bezludziu.', '', '', '', '', 0),
(4903, 'plPL', 'Rozkaz wodza', 'Na rozkaz wodza Krwawokła następujący mieszkańcy Iglicy Czarnej Góry mają zostać zgładzeni:$B$BOtyły postrach – Nadzorca Omokk.$B$BOkrutny i bezwzględny troll – Mistrz Wojenny Wun.$B$BNadrządca Wyrmthalak, poganiacz niższego miasta.$B$BMusisz też dostarczyć wszelkie ważne dokumenty, które znajdziesz.$B$BOdnieś sukces, a zyskasz chwałę.$B$BPonieś porażkę, a pójdziesz w zapomnienie.', 'Zabij Nadzorcę Omokka, Mistrza Wojennego Wuna i Nadrządcę Wyrmthalaka. Zdobądź ważne dokumenty Czarnej Skały. Gdy wykonasz misję, wróć do wodza Krwawokła w Kargacie.', '', 'Wróć do wodza Krwawokła w Kargacie na Bezludziu.', '', '', '', '', 0),
(4981, 'plPL', 'Agentka Bijou', 'Nigdy nie ufaj goblinom. Do tego to się sprowadza, $N.$B$BNazywa się Bijou – to jedna z naszych najśliskszych agentek. Dowiedziałem się, że pracowała dla jakiegoś podejrzanego handlarza egzotycznymi zwierzętami z Płonących Stepów, niejakiego Kiblera – krótko mówiąc, grała na dwa fronty. Co gorsza, finansowała swoje operacje z funduszy Hordy.$B$BChcę, żeby ją tu sprowadzić żywą.$B$BOstatnio widziano, jak wchodziła do Iglicy Czarnej Góry. Znajdź ją i przyprowadź z powrotem.$B$BI, $N, nie daj się jej omotać.', 'Udaj się do Iglicy Czarnej Góry i dowiedz się, co się stało z Bijou.', '', '', '', '', '', '', 0),
(4983, 'plPL', 'Raport zwiadowczy Bijou', 'Zanieś ten raport Lexlortowi. Oczyści moje dobre imię i z pewnością da S.E.K. przewagę strategiczną w starciach z tymi orkami.$B$BMam iść z tobą? Mam zdecydowanie za dużo roboty. Ruszaj, potrzebują tych raportów jak najszybciej!$B', 'Zanieś raport zwiadowczy Bijou arcymistrzowi Lexlortowi w Kargacie.$B', '', '', '', '', '', '', 0),
(5145, 'plPL', 'Garbarstwo smoczołuskie', 'Garbarstwo smoczołuskie nie jest łatwe, ale bardzo się opłaca. Nauczę cię wytwarzać tę wspaniałą zbroję kolczą, ale tylko jeśli przyjmiesz pewne warunki.$B$BWybierając tę ścieżkę, zgadzasz się, że nigdy nie nauczysz się garbarstwa żywiołów ani garbarstwa plemiennego; na szczycie tego rzemiosła jest miejsce tylko dla jednej z tych trzech dziedzin. Ponadto potrzebuję próbek twoich najlepszych wyrobów ze skorpiady. Wreszcie potrzebuję dowodu, że potrafisz zdobyć podstawowy surowiec tego fachu: łuski drakanów.', 'Przynieś 2 twarde napierśniki ze skorpiady, 2 twarde rękawice ze skorpiady i 10 zużytych smoczych łusek Thorkafowi Smoczemu Oku na Bezludziu.$B$BWykonanie tego zadania da ci dostęp do sztuki garbarstwa smoczołuskiego.$B$BWykonanie tego zadania uniemożliwi ci naukę garbarstwa żywiołów i garbarstwa plemiennego; zanim to zrobisz, upewnij się, że chcesz podążać tą ścieżką.', '', 'Wróć do Thorkafa Smoczego Oka na Bezludziu.', '', '', '', '', 0),
(7201, 'plPL', 'Ostatni żywioł', 'Dla tych, którzy zapuszczają się w głębiny, znajdzie się robota, $N.$B$BCzarnoryci opanowali tworzenie niezwykle potężnych golemów.$B$BPierwsze raporty naszych szpiegów wskazują, że krasnoludy używają wyjątkowego źródła mocy, które daje ich tworom niezrównaną siłę zabijania.$B$BWyobraź sobie tylko, co moglibyśmy zrobić z naszymi plugastwami, gdybyśmy położyli ręce na tej esencji żywiołów! Wywróć to miasto do góry nogami, jeśli trzeba, ale nie wracaj, dopóki nie znajdziesz esencji! Zapłata będzie warta ryzyka.', 'Udaj się do Otchłani Czarnej Góry i zdobądź 10 esencji żywiołów. Najpierw przychodzi ci do głowy, by przeszukać golemy i ich twórców. Pamiętasz też, że Vivian Lagrave mamrotała coś o żywiołakach.$B', '', 'Wróć do magini cienia Vivian Lagrave w Kargacie na Bezludziu.', '', '', '', '', 0),
(9439, 'plPL', 'Nieodebrany bagaż', 'To jest Kargat? O rety. Spodziewałem się, no... jakiejś osady, jakiegoś śladu cywilizacji tu, na tym pustkowiu.$B$BTo musi być pomyłka; ta nora pełna nieokrzesanych, niedomytych, rechoczących dzikusów z pewnością nie może być kwaterą główną Sił Ekspedycyjnych. Ci prostaccy barbarzyńcy mieli czelność się ze mnie śmiać, kiedy opowiedziałem im, jak Czarnoryci mnie okradli i zniknęli w Fortecy Angor. Mogę liczyć, że pomożesz mi odzyskać moje rzeczy i moją godność, prawda?', 'Odzyskaj plecak doradcy i rapier doradcy z miejsc, w których są przechowywane w Fortecy Angor, i zwróć je doradcy Sarophasowi w Kargacie.', '', 'Wróć do doradcy Sarophasa w Kargacie na Bezludziu.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(692, 'plPL', 'Ach, $gznalazłeś:znalazłaś; je! Dobra robota, $N! Może to nasza jedyna szansa przeciwko złu Myzrael!$b$bDaj mi tylko znaleźć mój klucz z grzechotką i sprawdzę, czy uda się poskładać te fragmenty...', 0),
(703, 'plPL', 'Ach, od razu zabiorę się za te skrzydła. Już prawie czuję ich smak!$b$bA tu masz przepis, gdyby przyszła ci ochota przyrządzić je samodzielnie!', 0),
(705, 'plPL', 'Będą świetne! Muszę je tylko roztłuc na proszek... potem wymieszać z odrobiną tego i odrobiną tamtego.$b$bUważajcie, padlinożercy! Szykujcie się na błysk!', 0),
(706, 'plPL', 'Ach tak, to się doskonale nada. Dzięki temu twoja broń będzie uderzać palącym żarem!', 0),
(709, 'plPL', 'Och, szczęście nam sprzyja! Dziękuję! Może jeszcze zdołamy się ocalić!', 0),
(710, 'plPL', 'Doskonale się nadadzą, $N. Dziękuję. Hmm, trochę więcej piasku, niż się spodziewałem. Trzeba będzie skorygować współczynnik tarcia. Nie, chwila; przy oleju mrozu i tak powinien być pomijalny.$B$B<Mamrocząc pod nosem, Lotwil wkłada pięść w otwartą dłoń drugiej ręki i wpatruje się w nie jak urzeczony.>', 0),
(711, 'plPL', '$N, po prostu niesamowite! Myślałem, że potrzeba by pół tuzina taurenów, żeby mi to wszystko przynieść.', 0),
(712, 'plPL', '$N, $gmyślałeś:myślałaś; kiedyś o tym, żeby zostać $gasystentem badawczym:asystentką badawczą;? Nie? Nie wiem, co ja tu pocznę bez twoich umiejętności. Inteligencja, ciekawość i siła – wszystko w jednym pakiecie.', 0),
(713, 'plPL', 'Zdumiewające! To powinno być idealne chłodziwo dla moich nowych karwaszy. Jeśli zaklęcia nie przetrwają stulecia, oddam cały swój dobytek Serwo.$B$BWszyscy magowie Zgromadzenia będą pod ogromnym wrażeniem, kiedy to skończę, $N. Zobaczysz.', 0),
(714, 'plPL', 'HA!$b$b<Lotwil wyrywa ci żyrochronatom.>$b$bIdealnie... prawie skończone. Nie, naprawdę. TERAZ już prawie kończę. Ten projekt to mój najwyższy priorytet... w tej chwili. Wsadzę to tylko na miejsce, a przekonasz się na własne oczy, w czego stworzeniu mi $gpomogłeś:pomogłaś;. Zajmie mi to jeszcze tylko kilka minut... może... możliwe, że dłużej. No, może dużo dłużej. Zobaczymy...', 0),
(715, 'plPL', 'TAK!$b$bTo znaczy... dziękuję, $N. Przydadzą się w podróży przez Bezludzie.', 0),
(716, 'plPL', 'Proszę bardzo, $N. Przymierz je.', 0),
(717, 'plPL', 'Kirin Tor nie będzie już musiał się martwić więźniami z Lethlor. Wrócę, by zameldować mojemu mistrzowi o sukcesie. Krasus z pewnością będzie zadowolony.', 0),
(718, 'plPL', 'Wielkie dzięki, $N. Kiedy cię nie było, ja... ee... połknąłem garść piasku. To było...$B$BNo, dość o tym. Dziś wieczorem pójdziemy zdobyć coś do jedzenia. Będziemy jeść jak królowie!', 0),
(719, 'plPL', 'Jesteś $gmoim wybawcą:moją wybawczynią;, $N. Cieszę się, że ktoś dał tym z Cienistej Kuźni nauczkę czy dwie. Dzięki za pomoc.', 0),
(720, 'plPL', 'Młotopalcy żyje?! To niesamowite, $N!', 0),
(732, 'plPL', 'Dobre wieści przynosisz wraz ze Znakiem, $N. Znak Ziemi stworzyli Czarnoryci z Fortecy Angor, by spętać dwóch bezwzględnych poruczników Śmiercioskrzydłego, bliźniaków Blacklasha i Hematusa.', 0),
(733, 'plPL', 'To jakiś początek, $N, i musi wystarczyć, dopóki nie dostaniemy wieści z Żelaznej Kuźni albo od Ligi Odkrywców.$B$BTeraz gdybym tylko gdzieś znalazł sól do beczki do hartowania...', 0),
(734, 'plPL', 'Zębatka nr 5, co? No, to nie wróży nic dobrego.', 0),
(777, 'plPL', 'Ach, doskonale. Odsuń się, bo zaraz znowu przejdę do historii!$b$b<Lotwil dalej gorączkowo pracuje.>', 0),
(778, 'plPL', 'Dziękuję, $N. To była niezła przeprawa, prawda?$b$bNie wiem, co mogło pójść nie tak. Dobrze, że moja magia była pod ręką i pomogła odesłać to stworzenie z powrotem na jego macierzysty plan.$b$bMoże mały wyraz wdzięczności za całą twoją ciężką pracę...', 0),
(779, 'plPL', 'Gdy umieszczasz kamienie runiczne w pasujących wgłębieniach, ziemią wstrząsa gwałtowny łoskot, a Pieczęć pęka.', 0),
(782, 'plPL', 'Teraz, gdy Tho\'grun nie żyje, a jego zwłoki ogołocą pustynne wiatry i padlinożerne sępy, wśród ogrów zapanuje chaos. To małe zwycięstwo, ale doprowadzi do znacznie większego.$B$BZnak Ziemi jest teraz w naszych rękach i możemy otworzyć więzienie czarnych smokowców w Lethlor. Uwolnimy je z wiecznej niewoli – choć na ich zgubę!', 0),
(793, 'plPL', 'Czarne Stado wciąż sprzymierza się ze zbuntowanymi orkami z Czarnej Skały i jednych, i drugich trzeba przywołać do porządku albo usunąć. Teraz, gdy Blacklash i Hematus nie żyją, możemy zwrócić uwagę na zachód, ku Iglicy Czarnej Góry.', 0),
(795, 'plPL', 'Gdy umieszczasz kamienie runiczne w pasujących wgłębieniach, ziemią wstrząsa gwałtowny łoskot, a Pieczęć pęka.', 0),
(1418, 'plPL', 'Helgrum chce raportu, co? Nie dalej niż trzy dni temu posłałam gońca do Stonardu. Nie wykonał zadania? Jeśli raport nie dotarł do Stonardu, to widać nie wykonał.$b$bMiejmy nadzieję, że następny goniec, którego poślę, będzie miał więcej umiejętności albo więcej szczęścia.', 0),
(1419, 'plPL', 'Niezła kolekcja żuchw, $N. Teraz te kojoty nie będą już rozszarpywać naszych zapasów w poszukiwaniu resztek.$B$BDobra robota. Kojoty z Bezludzia to niełatwa zdobycz. Twój czyn pokazuje mi, że może jednak tu przetrwasz.', 0),
(1420, 'plPL', 'Dziękuję, $N. Z raportu Neeki widzę, że Przymierze też ma swoje kłopoty. I może się okazać, że niektórych wrogów mamy wspólnych.', 0),
(1559, 'plPL', 'Więc jesteś $ginżynierem:inżynierką;, co? No to w podzięce za pomoc w zdobyciu tych pereł masz tu schemat bomby błyskowej.$b$bPowodzenia i postaraj się nie oślepić!', 0),
(2202, 'plPL', 'Dobra robota, $N, znów $gpokazałeś:pokazałaś;, ile jesteś $gwart:warta;! Te kapelusze będą ciekawym przedmiotem badań, jak nic!$B$BA teraz, zgodnie z obietnicą, skosztuj jednego z mocniejszych przywracających wywarów z moich prywatnych zapasów...$B$BJeśli znasz się na alchemii, może zrobimy jeszcze jakiś interes. Tak czy owak, dziękuję ci za pomoc!', 0),
(2203, 'plPL', 'Od alchemika dla alchemika – chylę czoła. Masz, weź tę recepturę i zapamiętaj ją dobrze. Niech przyniesie ci tyle sukcesów i nagród, ile mnie przez te wszystkie lata.', 0),
(2258, 'plPL', 'Ach, dobra robota! Na jakiś czas powinno mi to wystarczyć. Oto obiecana zapłata.$B$BJeśli cię to interesuje, przydałyby mi się jeszcze inne składniki. Te jednak można znaleźć tylko w głębi wykopalisk w Uldamanie. Niełatwo będzie je zdobyć, ale opłaci ci się, jeśli zechcesz znów mi pomóc.$B$BMoże coś więcej niż parę błyszczących monet, co?', 0),
(2278, 'plPL', 'Zgodnie z poleceniami kamiennego obserwatora ponownie uzyskujesz dostęp do Dysków Norgannona, teraz gdy $gpoznałeś:poznałaś; historię ziemnych, troggów i krasnoludów. Z wnętrza dysków dobiega cichy, krótki szum. Wtedy kamienny obserwator przemawia:$b$b„Dyski zostały zsyntetyzowane. Proszę ponownie uzyskać dostęp do Dysków Norgannona, aby otrzymać osobistą kopię”.', 0),
(2318, 'plPL', '$GPotężny:Potężna; $N, wiem, co robisz tu na Bezludziu. Wiem, że szukasz mojego daru języków. Chodzi ci o części tego naszyjnika, który $gznalazłeś:znalazłaś; w Uldamanie.$b$bZaskoczenie? Niepotrzebnie – moja praca polega na tym, żeby wiedzieć takie rzeczy. Porozmawiajmy raczej o tym, co zrobisz w zamian za przetłumaczony dziennik. Uwierz mi – nikt poza mną go nie przetłumaczy.$b$bCo więcej, złożę ci lepszą ofertę niż Dran Droffers, a i tak nadal będziesz $gmógł:mogła; dobić z nimi targu. Teraz cię to interesuje, co?', 0),
(2338, 'plPL', 'Znasz się na dobrym interesie – wiedziałem, że mogę na tobie polegać.$b$bTo potrwa tylko chwilę – rzucę zaklęcie, które szybko przełoży ludzką mowę na postać, którą zrozumiesz. Jestem trollem, który dotrzymuje słowa; spytaj kogokolwiek w Hordzie o Jarkala Mchosplota. No, zaczynajmy...', 0),
(2339, 'plPL', 'Bardzo dobrze, $N. Teraz owoce naszego fortelu sowicie się opłacą. Skończyłem z samym naszyjnikiem i jestem pewien, że potrafię niezawodnie odtworzyć proces jego wykonania.$B$BNajpierw jednak użyję specjalnie przygotowanej inkantacji, by szybko przeanalizować te klejnoty, zanim zaniesiesz je razem z naszyjnikiem z powrotem do Orgrimmaru. To zajmie tylko krótką chwilę.', 0),
(2418, 'plPL', 'Świetnie, $gznalazłeś:znalazłaś; trochę! Wielkie dzięki, $N. Nie spotkałem jeszcze nikogo tak niezawodnego jak ty!$B$BNie mogę się doczekać, aż wypróbuję je na kilku urządzeniach, przy których majstruję. Założę się, że w odpowiednich warunkach urządzenia zasilane tymi kamieniami będą działać, i działać, i działać...', 0),
(3821, 'plPL', 'Mój biedny Thal\'trak.$B$BPlanowaliśmy zamieszkać z moją matką i ojcem w Zaziemiu, kiedy skończymy służbę. Teraz te plany legły w gruzach!', 0),
(3822, 'plPL', '<Thal\'trak osuwa się na ziemię.>$B$BMieliśmy się przenieść do Zaziemia. Mówiła ci? To miała być jej ostatnia misja.$B$B<Thal\'trak szlocha.>$B$BNie chcę go, $N. Zatrzymaj go, wyrzuć, wszystko mi jedno! Ten kolczyk nic już dla mnie nie znaczy. Nie bez niej...', 0),
(3906, 'plPL', 'To nie może być... to nie może tak być. Zniszczenie Pyrona zaledwie uchyliło zasłonę. W głębinach Czarnej Góry kryje się znacznie podstępniejsze źródło skażenia.', 0),
(3907, 'plPL', '<Gromoserce ściska tablicę Kurniyi.>$b$bRagnaros... tutaj...$b$bStarszyzna słusznie obawiała się skażenia płynącego z Czarnej Góry. Generał Przedwiecznych! W NASZYM ŚWIECIE! Musimy ponownie ocenić nasze położenie tu, w Kargacie. Musimy zdecydować, czy zostajemy i walczymy, czy uciekamy w obawie przed nowym rozłamem.$b$bStrzeż się dalszych wypraw do Czarnej Góry, $N. W tych ognistych głębinach mieszka zło znacznie większe niż cokolwiek, co istnieje na tym świecie.', 0),
(3911, 'plPL', 'Wspaniale! Natychmiast każę wysłać je kurierem do Podmiasta!$B$BA co do ciebie – oto zapłata, tak jak obiecałam. Reszty nie trzeba, ty plugawa bestio!', 0),
(3981, 'plPL', 'Nie mamy wiele czasu. Słuchaj uważnie, $N. To, co mam ci do powiedzenia, jest tajne i przeznaczone wyłącznie dla twoich uszu.', 0),
(4061, 'plPL', '<Theodora rozkłada przed sobą fragmenty.>$b$b<Theodora uważnie bada fragmenty przez ogromny monokl.>$b$bCiekawe. W strukturę każdego z tych fragmentów wyryto... inicjały.', 0),
(4062, 'plPL', '<Twarz Lotwila robi się biała jak kreda.>$b$bJa... znam te oznaczenia.', 0),
(4063, 'plPL', 'Co to jest?!? Ta głowa nie jest z ciała. To jakiś twór Czarnorytych: cień Argelmacha – kolejna MASZYNA! Podejrzewam, że twoje zwycięstwo nad Argelmachem nie potrwa długo, bo wkrótce powstanie następny, by zająć miejsce „tego czegoś”.', 0),
(4081, 'plPL', 'Ten pierwszy cios powinien nieźle pognieść Kuźni Gniewu spodnie. A teraz odmaszerować, żołnierzu. Mam robotę do skończenia, bitwy do zaplanowania i wrogów do zmiażdżenia!$B$BSprawdź listy gończe, jeśli chcesz więcej roboty.', 0),
(4082, 'plPL', 'Kuźnia Gniewu bez wątpienia... się gniewa. Wróć do mnie, gdy zdobędziesz trzecią nagrodę, a przystąpimy do operacji „Śmierć Kuźni Gniewu”. Nie mogę zdradzić szczegółów, ale bądź $gpewien:pewna;, że ktoś przy tym zginie.', 0),
(4121, 'plPL', 'Twoje bohaterstwo nie pozostanie bez uznania, $N. $GZasłużyłeś:Zasłużyłaś; na tę nagrodę. Wódz porozmawia teraz z tobą o ostatniej misji.', 0),
(4122, 'plPL', 'Nie widzisz, jaką moc zyskujemy, wstępując do legionu Czarnej Skały?', 0),
(4132, 'plPL', 'Nareszcie! Łotr poniósł karę! Z ciebie ktoś wyjątkowy, $N. Noś ten medalion jako symbol swojego niezłomnego oddania Hordzie i S.E.K.', 0),
(4134, 'plPL', 'Bardzo dobrze. Wyślę ten przepis do Aptekarium do zbadania, a z czasem odkryjemy jego tajemnice. Pewnego dnia krasnoludy z Przymierza mogą się przekonać, że zalety tego trunku obrócono przeciwko nim!$b$bWydaje mi się to okropnie zabawne. Może śmierć wpływa na poczucie humoru... jak sądzisz?', 0),
(4724, 'plPL', 'Wściekłe szczenięta? Gizrul Ślinotok? I $gprzeżyłeś:przeżyłaś;, by o tym opowiedzieć?! Niesamowite! Zasłużona nagroda!', 0),
(4768, 'plPL', 'Doskonale. Formuły wyryte na tej tablicy pochłoną całe dni badań, ale jestem pewna, że te badania wydadzą słodkie owoce.$b$bDziękuję, $N. Twoja pomoc jest dla nas bezcenna.', 0),
(4903, 'plPL', '<Matowa zielona skóra wodza Krwawokła na krótką chwilę blednie jak ściana.>', 0),
(4981, 'plPL', 'Nie będę cię okłamywać, $N. Potrzebowałam pieniędzy! Kibler płaci bardzo, bardzo dobrze – o wiele lepiej, niż S.E.K. kiedykolwiek mogłyby.$b$bAle nie wątp w moją lojalność! Jak myślisz, po co tu jestem? Żeby zdobyć dla tego szalonego goblina jaja egzotycznych zwierząt albo coś równie niedorzecznego? Nie, tylko kompletny głupek przyszedłby do Iglicy Czarnej Góry zbierać zwierzaki. No, nie sądzę, żeby na tym świecie było wielu takich ludzi.$b$b<Bijou się śmieje.>$b$bTylko tego brakuje, żeby tacy ludzie się rozmnażali.', 0),
(4983, 'plPL', 'Muszę jej to przyznać: znowu wywinęła się z trudnego położenia! Te raporty okażą się bezcenne w naszych rozgrywkach z orkami z Czarnej Skały.$b$bOczywiście zostaniesz $gwynagrodzony:wynagrodzona; za swoją ciężką pracę.', 0),
(5145, 'plPL', 'Muszę ci przyznać – trzeba silnej woli, by podjąć tak ostateczną decyzję jak ty przed chwilą. Zapewniam cię, że garbarstwo smoczołuskie okaże się dla ciebie opłacalną i satysfakcjonującą ścieżką.$b$bGdy w przyszłości zechcesz się szkolić w tej sztuce, po prostu ze mną porozmawiaj, a udostępnię ci całą wiedzę, której jeszcze nie $gprzyswoiłeś:przyswoiłaś;.', 0),
(7201, 'plPL', 'Wspaniale! Natychmiast każę wysłać je kurierem do Podmiasta!$B$BA co do ciebie – oto zapłata, tak jak obiecałam. Reszty nie trzeba, ty plugawa bestio!', 0),
(9439, 'plPL', 'Czynisz cuda, $N! Mówię ci, jeszcze nigdy w życiu tak bardzo nie pragnąłem się przebrać.$B$BI mój rapier! Bez ostrza czułem się wręcz nagi.$B$BNależą ci się pochwała i nagroda za twoje starania. Niech nikt nie mówi, że Sarophas nie docenia maluczkich, którzy pomogli mu po drodze!', 0),
(11766, 'plPL', 'Zbezcześć wielkie ognisko Hordy na Bezludziu!', 0),
(11842, 'plPL', 'Uczcij płomień Bezludzia!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(692, 'plPL', '$GZnalazłeś:Znalazłaś; te fragmenty?!?! Zwój Myzrael będzie ci potrzebny, jeśli chcesz ją znowu uwięzić, zanim będzie za późno!', 0),
(703, 'plPL', 'Witaj, $N. $GPrzyniosłeś:Przyniosłaś; moje skrzydła?', 0),
(705, 'plPL', 'Masz moje perły? Prawie skończyły mi się bomby błyskowe!', 0),
(706, 'plPL', 'Jak idą łowy, $N?', 0),
(709, 'plPL', '$GZnalazłeś:Znalazłaś; tabliczkę? Musi skrywać tajemnice! Tajemnice, które nas ocalą!', 0),
(710, 'plPL', 'To miejsce jest idealne do... Możesz to na chwilę przytrzymać? Tak, właśnie tak, wzdłuż wektora normalnego. No więc, co ja... A tak. Idealne do testowania mojego najnowszego projektu. Surowce, otwarta przestrzeń... czego więcej może chcieć inteligentny i oświecony adept sztuk tajemnych?', 0),
(711, 'plPL', 'Jestem bardzo zadowolony, $N. Moje zaklęcia podziałały na mniejsze kawałki dokładnie tak, jak przewidziałem. Jeśli ten eksperyment powiedzie się tak, jak przewiduję, żywiołaki, którymi będę w stanie władać, przyćmią wszystko, co kiedykolwiek wcześniej przyzwano.', 0),
(712, 'plPL', 'Kamienne płyty, które $gznalazłeś:znalazłaś;, były idealne, $N. Gdy tu skończymy, Lucien zabierze te zapasowe z powrotem do Kharanos. W końcu mogą się jeszcze przydać.$B$BNa przykład byłyby świetną podstawą poręcznego schronu, kiedy zacznę badać interdyscyplinarne podejście do materiałów wybuchowych o dużej mocy...', 0),
(713, 'plPL', '$GZnalazłeś:Znalazłaś; olej, którego potrzebuję? Bardzo by mi pomogło, gdyby udało ci się go zdobyć.', 0),
(714, 'plPL', 'Tak, tak, tak. Chwileczkę.$B$B<Lotwil dalej majstruje przy jakimś ustrojstwie.>', 0),
(715, 'plPL', 'Jest coraz bliżej ukończenia. Jak idzie po twojej stronie?', 0),
(716, 'plPL', 'Nie zwlekałbym zbyt długo z tymi karwaszami, $N.$b$bKto wie, co się jeszcze wydarzy?', 0),
(717, 'plPL', 'Potężna magia i moce przez długi czas utrzymywały więzienie smokowców, ale nie możemy dopuścić choćby cienia możliwości, że Blacklash i Hematus zostaną uwolnieni.', 0),
(718, 'plPL', 'Na pustyni lepiej nie być głodnym, $gprzyjacielu:przyjaciółko;, mówię ci.$B$BHej... co to tam jest...', 0),
(719, 'plPL', 'Nie wiem, czego szukali ci z Cienistej Kuźni, ale na pewno mieli jakiś cel.', 0),
(732, 'plPL', 'Ta koczownicza banda ogrów wędruje między swoimi obozami na Bezludziu; żar bijący od suchej ziemi i wirujące wiatry utrudniają śledzenie jej wędrówki. Słyszałem, że czasem przechodzą przez Obóz Boff. Jeśli się zgubisz, spróbuj szukać tam.', 0),
(733, 'plPL', 'No, poradziłem sobie z tym, co miałem, ale... tego niewiele. $GZnalazłeś:Znalazłaś; jeszcze jakieś zapasy?', 0),
(777, 'plPL', '<Nie podnosząc wzroku znad kajdan, Lotwil wyciąga rękę i niecierpliwie porusza palcami.>$B$BZębatka, $N, zębatka!', 0),
(778, 'plPL', 'Nie całkiem takiego wyniku się spodziewałem. $GMógłbyś:Mogłabyś; odzyskać moje kajdany?', 0),
(779, 'plPL', 'Tu spoczywa Pieczęć Ziemi z trzema wgłębieniami na ametystowy kamień runiczny, opalowy kamień runiczny i diamentowy kamień runiczny.', 0),
(782, 'plPL', 'Zdrada Tho\'gruna... czy to dziwne, że ogry nie należą już do Hordy? Chętnie zobaczę go martwego, a Znak Ziemi odzyskany.$B$BJeśli jeszcze się z nim nie $grozprawiłeś:rozprawiłaś;, nie trać czasu i ruszaj do Obozu Boff. Leży na południowy wschód od Kargatu.', 0),
(793, 'plPL', 'Niewielu jest wrogów groźniejszych niż smoczy ród i niewiele smoków walczyło tak zaciekle jak Blacklash i Hematus.', 0),
(795, 'plPL', 'Tu spoczywa Pieczęć Ziemi z trzema wgłębieniami na ametystowy kamień runiczny, opalowy kamień runiczny i diamentowy kamień runiczny.', 0),
(1419, 'plPL', 'Masz żuchwy?', 0),
(1420, 'plPL', '$GWróciłeś:Wróciłaś;. Masz raport?', 0),
(2258, 'plPL', 'Masz już to, czego potrzebuję? Nie dostaniesz zapłaty, dopóki nie przyniesiesz mi tych składników.', 0),
(2278, 'plPL', 'Głos kamiennego obserwatora zdaje się rozbrzmiewać w samej głębi twojego jestestwa:$b$b„Najpierw należy spełnić warunek wstępny asymilacji danych Dysków Norgannona; po spełnieniu tego wymogu zostanie udzielona zgoda na pobranie przenośnej wersji przechowywanych danych. Proszę się najpierw upewnić, że informacje zawarte w tym repozytorium zostały w pełni przejrzane”.', 0),
(2338, 'plPL', '$GPrzemyślałeś:Przemyślałaś; to, co? Mądrze zrobisz, jeśli przyjmiesz ten układ – ty i ja dostaniemy to, na czym nam zależy, a Złomowisko Droffers i Syn będzie myśleć, że dostaje to, czego chce.', 0),
(2339, 'plPL', 'Czeka cię kolejna wyprawa w głąb Uldamanu, jeśli nie masz klejnotów i źródła mocy zdolnego z powrotem tchnąć w naszyjnik magiczną moc.$B$BKlejnoty dostaniesz z powrotem, żeby zanieść je tym osiłkom w Orgrimmarze; źródło mocy zatrzymam ja, bo to właśnie ono sprawi, że naszyjnik w ogóle zadziała...', 0),
(2418, 'plPL', 'Masz kamienie mocy, $N? Mam tu mechanicznego gryzonia, który potrzebuje zasilania...', 0),
(3822, 'plPL', '$GZnalazłeś:Znalazłaś; Sha\'ni? Nic jej nie jest?', 0),
(3906, 'plPL', 'Żywioły wciąż są w nieładzie, $N.', 0),
(3907, 'plPL', 'Płomienie wkrótce ogarną te ziemie. Pospiesz się, $N!', 0),
(3911, 'plPL', 'Pokaż mi je!', 0),
(4061, 'plPL', 'Nie lekceważ tego zadania, $N!', 0),
(4062, 'plPL', 'Co tam masz, $N?', 0),
(4063, 'plPL', 'To był on? Naprawdę żył?', 0),
(4081, 'plPL', 'Czego, $N? Nie widzisz, że dowodzę plutonem?$B$B', 0),
(4082, 'plPL', 'Znowu ty? Muszę ci przyznać, $N, jesteś $guparty:uparta;.', 0),
(4121, 'plPL', 'Zabiorę tę zdradziecką kanalię, $N.', 0),
(4132, 'plPL', 'Czy Rzeźnik z Czarnej Góry został już usunięty?', 0),
(4134, 'plPL', 'Masz przepis na Lager Gromowarów, $N?', 0),
(4724, 'plPL', 'Skoro pani sfory nie żyje, możemy zacząć przetrzebiać worgi wartownicze w Iglicy i w końcu przebić się do miasta.', 0),
(4768, 'plPL', '$GZnalazłeś:Znalazłaś; tablicę, $N? Nie mogę się doczekać, by zgłębić jej tajemnice.', 0),
(4903, 'plPL', '<Wódz Krwawokieł salutuje.>', 0),
(4983, 'plPL', 'Gdzie ta goblinka???', 0),
(5141, 'plPL', 'Jeśli jesteś $ggotów:gotowa; podjąć ostateczną decyzję i zostać $gsmoczołuskim garbarzem:smoczołuską garbarką;, jestem gotów przyjąć cię na ucznia. Przynieś mi tylko to, o co prosiłem, a rozpoczniemy twoją naukę.', 0),
(5145, 'plPL', 'Jeśli jesteś $ggotów:gotowa; podjąć ostateczną decyzję i zostać $gsmoczołuskim garbarzem:smoczołuską garbarką;, jestem gotów przyjąć cię na ucznia. Przynieś mi tylko to, o co prosiłem, a rozpoczniemy twoją naukę.', 0),
(7201, 'plPL', 'Pokaż mi je!', 0),
(9439, 'plPL', 'Na litość Słońcobieżców, nie gap się na mnie! Dość, że muszę tu wytrzymywać w brudnym ubraniu! Po tym wszystkim, co przeszedłem, tylko tego mi brakuje, żeby ktoś się na mnie gapił. Udało ci się odzyskać moje rzeczy z tej dziury w ziemi, którą Czarnoryci nazywają fortecą?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(2817, 0, 'plPL', 'Musisz być w nie lada biedzie, skoro włóczysz się po tym Bezludziu, $N. W biedzie, tak jak ja.$B$BA może jesteś tu, bo masz nierówno pod sufitem. Tak jak ja.', 0),
(2860, 0, 'plPL', 'Niezła to była ucieczka, powiem ci, $N. Łapaliśmy wszystko, co nie było przybite gwoździami albo dało się szybko zabrać. Przez to trochę nam brakuje zapasów.', 0),
(2920, 0, 'plPL', 'Witaj, $N.$B$BLotwil nie jest najbardziej spostrzegawczym szefem, jakiego miałem. Naprawdę bardzo angażuje się w swoją pracę. Tak bardzo, że czasem jego służba nie je albo nie dostaje zapłaty.$B$B<Lucien spogląda krzywo na Lotwila.>$B$BAle to nie znaczy, że ty masz na tym cierpieć.', 0),
(2921, 0, 'plPL', 'Jak dobrze, że się zjawiasz, $N.$B$BNazywam się Lotwil Veriatus i jestem członkiem założycielem Oświeconego Zgromadzenia Nauk Arkanologicznych, Alchemicznych i Inżynieryjnych: dążymy do połączenia rozumnych nauk Azeroth w jedną wszechstronną szkołę.', 0),
(5394, 0, 'plPL', 'Nie przejmuj się upałem. Na Bezludziu upał to najmniejsze z twoich zmartwień.', 0),
(9081, 0, 'plPL', 'Nigdy nie pudłuję...', 0);
