INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(711, 'plPL', 'Helgrumie,$B$BMoje wyrazy uznania dla tego, kto wydał rozkaz założenia naszej bazy w Kargacie na Bezludziu. To idealne miejsce do szkolenia naszych wojsk. Surowy klimat, groźna dzika zwierzyna, wojowniczy tubylcy i całkowity brak wsparcia z zewnątrz czynią z niego tygiel, z którego wyjdą tylko najlepsi wojownicy i zwiadowcy.$B$BDobry plan. Świetna robota.', 0),
(712, 'plPL', 'Opiszę okoliczne ziemie tak, jak zbadali je zwiadowcy z Kargatu:$B$B– Czerwone, skaliste wzgórza i suche równiny, na których życie ledwie się utrzymuje.$B– Palące słońce i gwałtowne wiatry.$B– Żadnych jezior ani strumieni. Nawet pojedynczych sadzawek. Żeby znaleźć wodę, mieszkańcy muszą kopać głębokie, błotniste studnie albo wysysać skąpą wilgoć z rzadkich kaktusów czy kolczastych chwastów.$B$BKrótko mówiąc: gorące, ciężkie życie.', 0),
(713, 'plPL', 'Bezludzie roi się od wrogów. Po rozżarzonych piaskach krążą ogry, które napadają na nieostrożnych. Czarnoryci zajmują koszary na wschód od Kargatu i walczą ze swoimi jaśniejszymi pobratymcami w Loch Modan na północy. Brutalne, prymitywne bestie zwane troggami nawiedzają każdy skrawek cienia, jaki znajdą, i zaciekle go bronią.$B$BA we wschodniej części Bezludzia, w Parowie Lethlor, są smoki. Nie wiemy, ile ich jest ani jak są duże, bo zwiadowcy, którzy podchodzą zbyt blisko, nigdy nie wracają.', 0),
(714, 'plPL', 'Nie trzeba chyba mówić, że my – garnizon Kargatu – jesteśmy bardzo zadowoleni z tego przydziału. Trzymamy się tu twardo, bo jeśli zmiękniemy, zginiemy.$B$BI nie chciałabym, żeby było inaczej.$B$BNeeka Krwawa Blizna$BGłówna zwiadowczyni, Kargat', 0);
