INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(887, 'plPL', '%s przyrządza dla $n porcję ostrych, pikantnych skrzydeł sępa.', '', 0),
(898, 'plPL', 'Biegle władam ponad 4 językami.', '', 0),
(899, 'plPL', 'Brzt... klik... wrrr...', '', 0),
(900, 'plPL', 'Panie, gdzie się podziały wszystkie drzewa?', '', 0),
(901, 'plPL', 'Możemy to ulepszyć. Uczynić silniejszym, szybszym. Mamy technologię. Mamy magię.', '', 0),
(902, 'plPL', 'Pewnego dnia będę prawdziwym chłopcem.', '', 0),
(903, 'plPL', 'Na Bezludziu bywa naprawdę gorąco. Ale przynajmniej to suchy upał.', '', 0),
(904, 'plPL', 'Wihajstry... odhaczone. Dynksy... odhaczone. Furkotki... odhaczone.', '', 0),
(905, 'plPL', 'Tu jest niebezpiecznie, panie. Ale pomogę trzymać straż.', '', 0),
(906, 'plPL', '%s zaczyna trzepotać skrzydłami i głośno skrzeczeć. Masz przeczucie, że zaraz staniesz się jego następnym posiłkiem!', '', 0),
(907, 'plPL', '%s wyraźnie się uspokaja – $n $gposłużył:posłużyła; mu za posiłek.', '', 0),
(948, 'plPL', 'Czas przetestować mój projekt!', '', 0),
(949, 'plPL', 'O nie! Wymknął się spod kontroli! Uciekajcie!', '', 0),
(950, 'plPL', 'Chyba muszę coś z tym zrobić!', '', 0),
(951, 'plPL', 'Chronić pana!', '', 0),
(959, 'plPL', '%s nerwowo zerka na Lotwila.', '', 0),
(1021, 'plPL', '%s miele perły, które $gprzyniósł:przyniosła; mu $n...', '', 0),
(1022, 'plPL', 'Uwaga! Atakuje nas $n!', '', 0),
(1023, 'plPL', 'No i proszę. Nowa porcja bomb błyskowych!', '', 0),
(1024, 'plPL', 'Masz, bestio!', '', 0),
(1025, 'plPL', '%s rzuca laskę dynamitu, która ląduje nieopodal.', '', 0),
(4692, 'plPL', 'Dobra robota, żołnierze! Spocznij!', '', 0),
(4903, 'plPL', 'Znam drogę, insekcie. Nie musisz mnie popędzać jak bydło.', '', 0),
(4904, 'plPL', 'Chyba nie myślisz, że ta napaść ujdzie ci na sucho. Przyjdą po mnie, a ty zapłacisz za swoją zuchwałość.', '', 0),
(4905, 'plPL', 'NADZIAĆ ICH, BRACIA!', '', 0),
(4906, 'plPL', 'Wątpię, by szczęście dopisało ci tak samo, gdy następnym razem spotkasz moich pobratymców.', '', 0),
(4907, 'plPL', 'Idą po ciebie, $ggłupcze:głupia;!', '', 0),
(4908, 'plPL', 'Co chcesz przez to osiągnąć, $ggłupcze:głupia;? Nawet teraz armie Czarnej Skały szykują się, by zniszczyć twój świat.', '', 0),
(4909, 'plPL', 'Nadlatują na najczarniejszych skrzydłach. Szykuj się na swój koniec!', '', 0),
(4911, 'plPL', 'Najgorsze dopiero nadejdzie!', '', 0),
(4913, 'plPL', 'Czas na twoją ostatnią walkę, insekcie.', '', 0),
(4918, 'plPL', '%s poddaje się.', '', 0),
(4927, 'plPL', 'Chcesz się bawić? To się pobawmy!', '', 0),
(5059, 'plPL', 'Odrodzę się, śmiertelnicy! Incendius wskrzesi mnie z tych popiołów!', '', 0),
(5061, 'plPL', 'Nie można mnie zniszczyć! Z woli Ragnarosa odrodzę się!', '', 0),
(5271, 'plPL', 'Nie ukryjesz się przed nami. Szykuj się, spłoniesz!', '', 0),
(5548, 'plPL', '%s wydaje z siebie gardłowy warkot, a jej ciało osuwa się na ziemię. Salami Iglicy Czarnej Góry niesie się echem przerażające wycie. Coś jest bardzo, bardzo rozgniewane.', '', 0),
(6291, 'plPL', 'Twój smród zwabi wszystkie smoki w promieniu wielu mil. Mów, czego chcesz, i to szybko.', '', 0),
(9091, 'plPL', 'Skanowanie form życia... nie znaleziono celu', '', 0),
(9092, 'plPL', 'Wykryto nieznane formy życia... trwa ocena...', '', 0),
(9093, 'plPL', 'Cel utracony... wznawiam wzorzec poszukiwań Delta', '', 0),
(18976, 'plPL', 'Zapomnienia garbarstwa smoczołuskiego nie należy traktować lekko. Jeśli z niego zrezygnujesz, zapomnisz też wszystkie wykroje, które wymagają garbarstwa smoczołuskiego!', 'Zapomnienia garbarstwa smoczołuskiego nie należy traktować lekko. Jeśli z niego zrezygnujesz, zapomnisz też wszystkie wykroje, które wymagają garbarstwa smoczołuskiego!', 0),
(18977, 'plPL', 'Chcę zapomnieć garbarstwo smoczołuskie!', 'Chcę zapomnieć garbarstwo smoczołuskie!', 0),
(47168, 'plPL', 'Musisz spróbować tego piwa.', '', 0);
